import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import {execFileSync} from 'node:child_process';
const assets=JSON.parse(fs.readFileSync('.github/scripts/assets.json','utf8'));
let pending=[...assets.runtime];
await Promise.all(Array.from({length:6},async()=>{while(pending.length){const item=pending.shift();let good=false;for(let attempt=0;attempt<3;attempt++){try{const url='https://raw.githubusercontent.com/ps3addict/'+item.repo+'/'+assets.refs[item.repo]+'/'+item.path;const response=await fetch(url);if(!response.ok)throw new Error('HTTP '+response.status);const data=Buffer.from(await response.arrayBuffer());const hash=crypto.createHash('sha1').update('blob '+data.length+'\0').update(data).digest('hex');if(data.length!==item.size||hash!==item.sha)throw new Error('Hash mismatch: '+item.path);const target=item.repo+'/'+item.path;fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,data);console.log('Verified '+target);good=true;break;}catch(error){if(attempt===2)throw error}}if(!good)throw new Error('Download failed')}}));
const storedPackage='source/Latest_HEN_Installer_3.4.0_signed-492C.pkg';const data=fs.existsSync(storedPackage)?fs.readFileSync(storedPackage):Buffer.concat(assets.chunks.map(name=>fs.readFileSync('.source-chunks/'+name)));if(data.length!==assets.sourceSize||crypto.createHash('sha256').update(data).digest('hex')!==assets.sourceSha256)throw new Error('Local source package hash mismatch');
for(const target of ['source/Latest_HEN_Installer_3.4.0_signed-492C.pkg','source/files/Latest_HEN_Installer_3.4.0_signed-492C.pkg'])fs.writeFileSync(target,data);
for(const name of assets.chunks){if(fs.existsSync('.source-chunks/'+name))fs.unlinkSync('.source-chunks/'+name)}if(fs.existsSync('.source-chunks'))fs.rmdirSync('.source-chunks');
execFileSync('python3',['-c','import pathlib,zipfile; root=pathlib.Path("source/files"); z=zipfile.ZipFile("source/PS3HEN_3.4.0_4.92_FW.zip","w",zipfile.ZIP_DEFLATED); [(z.write(p,"PS3HEN_3.4.0_4.92_FW/"+p.relative_to(root).as_posix())) for p in sorted(root.rglob("*")) if p.is_file()]; z.close()']);
console.log('Prepared all 20 HEN packages and the verified local source archive.');